/**
 * Regression tests for the Class XI Physics paper reported by the user.
 *
 * The uploaded paper and official solutions were not present in the
 * repository, so these fixtures reproduce the reported structure exactly:
 * Section A 3 marks, Section B 6 marks, Section C 16 marks, total 25, with Q6
 * and Q7 at 2 + 3 + 3. Tests marked "real document" run on the actual PDF
 * bytes generated by scripts/make-physics-fixtures.ts; the rest exercise the
 * same parser with extraction text, including the merged lines and OCR errors
 * a real upload produces.
 */
import { describe, expect, it } from 'vitest';
import { parsePaper } from '../src/exam/paper';
import { evaluatePaper } from '../src/exam/grade';
import type { Paper, PaperQuestion } from '../src/exam/model';
import { decisionChat, refsInPrompt, type ChatCall } from './helpers';

const HEADER = `Class XI Physics — Unit Test
Time: 1 hour 30 minutes            Maximum Marks: 25

General Instructions:
1. All questions are compulsory.
2. Marks for each question are indicated against it.
`;

const CLEAN = `${HEADER}
SECTION A

1. Which physical quantity is a vector quantity? 1
(a) speed   (b) velocity   (c) distance   (d) mass
2. The slope of a velocity-time graph represents which physical quantity? 1
(a) displacement   (b) velocity   (c) acceleration   (d) force
3. A ball is thrown vertically upward with a speed of 20 m/s. Taking g = 10 m/s2,
calculate its maximum height. 1

SECTION B

4. State Newton's second law of motion and derive the relation F = ma. 3
5. Define the work done by a constant force and state its SI unit. 3

SECTION C

6. A projectile is fired from the ground with a speed of 20 m/s at an angle of
30 degrees to the horizontal. Calculate:
(a) the time of flight. 2
(b) the maximum height reached. 3
(c) the horizontal range. 3

7. A block of mass 5 kg is pulled along a rough horizontal surface by a
horizontal force of 25 N. The coefficient of kinetic friction is 0.3.
Take g = 10 m/s2.
(a) Draw the free-body diagram of the block. 2
(b) Calculate the frictional force acting on the block. 3
(c) Calculate the net acceleration of the block. 3
`;

/** What a two-column or tightly-spaced PDF text layer produces: one long line. */
const MERGED = `${HEADER}
SECTION A
1. Which physical quantity is a vector quantity? (a) speed (b) velocity (c) distance (d) mass 1 2. The slope of a velocity-time graph represents which physical quantity? (a) displacement (b) velocity (c) acceleration (d) force 1 3. A ball is thrown vertically upward with a speed of 20 m/s. Taking g = 10 m/s2, calculate its maximum height. 1
SECTION B
4. State Newton's second law of motion and derive F = ma. 3 5. Define work and state its SI unit. 3
SECTION C
6. A projectile is fired at 20 m/s at 30 degrees. (a) Find the time of flight. 2 (b) Find the maximum height. 3 (c) Find the horizontal range. 3
7. A 5 kg block is pulled by 25 N with mu = 0.3. (a) Draw the free-body diagram. 2 (b) Find friction. 3 (c) Find acceleration. 3`;

/** What OCR gives on the same page: Q read as O/l, punctuation dropped. */
const OCR_TEXT = `${HEADER}
SECTION A
Ql. Which physical quantity is a vector quantity?
(a) speed (b) velocity (c) distance (d) mass 1
O2. The slope of a velocity-time graph represents which physical quantity?
(a) displacement (b) velocity (c) acceleration (d) force 1
Q 3. A ball is thrown vertically upward with a speed of 20 m/s. Taking g = 10 m/s2,
calculate its maximum height. 1
SECTION B
4, State Newton's second law of motion and derive F = ma. 3
5) Define work done by a constant force and state its SI unit. 3
SECTION C
6. A projectile is fired at 20 m/s at 30 degrees. Calculate
(a) the time of flight. 2
(b) the maximum height. 3
(c) the horizontal range. 3
7. A 5 kg block is pulled by 25 N, mu = 0.3. Take g = 10 m/s2.
(a) Draw the free-body diagram. 2
(b) Calculate the frictional force. 3
(c) Calculate the net acceleration. 3`;

const ANSWERS = `Q1. (b) velocity
Q2. (c) acceleration
Q3. H = u^2 / 2g = (20 x 20) / 20 = 20 m.
Q4. Newton's second law: the rate of change of momentum is proportional to the applied force, F = dp/dt = ma.
Q5. Work = force x displacement in the direction of the force; SI unit joule (J).
Q6. (a) T = 2u sin(theta)/g = 2 s. (b) H = u^2 sin^2(theta)/(2g) = 5 m. (c) R = u^2 sin(2theta)/g = 34.6 m.
Q7. (a) Weight 50 N downward, normal reaction 50 N upward, applied force 25 N forward, friction 15 N backward.
(b) f = mu N = 0.3 x 50 = 15 N.
(c) F_net = 25 - 15 = 10 N, so a = F_net / m = 10 / 5 = 2 m/s2.`;

function find(paper: Paper, ref: string): PaperQuestion {
  const question = paper.questions.find(item => item.ref === ref);
  if (!question) throw new Error(`Question ${ref} was not detected. Found: ${paper.questions.map(item => item.ref).join(', ')}`);
  return question;
}

function totalFor(paper: Paper, parentKey: string): number {
  return paper.questions
    .filter(question => question.parentKey === parentKey)
    .reduce((sum, question) => sum + (question.max ?? 0), 0);
}

function parents(paper: Paper): string[] {
  return [...new Set(paper.questions.map(question => question.parentKey))];
}

const ALL_REFS = [
  'Q1',
  'Q2',
  'Q3',
  'Q4',
  'Q5',
  'Q6(a)',
  'Q6(b)',
  'Q6(c)',
  'Q7(a)',
  'Q7(b)',
  'Q7(c)',
];

describe('Class XI Physics paper: question recognition', () => {
  it('identifies Q1, Q2 and Q3 that were previously missing', () => {
    const paper = parsePaper(CLEAN);
    expect(find(paper, 'Q2').text).toContain('slope of a velocity-time graph');
    expect(find(paper, 'Q3').text).toContain('thrown vertically upward');
    expect(parents(paper)).toEqual(['1', '2', '3', '4', '5', '6', '7']);
  });

  it('splits question numbers that a PDF text layer merged into one line', () => {
    const paper = parsePaper(MERGED);
    expect(parents(paper)).toEqual(['1', '2', '3', '4', '5', '6', '7']);
    expect(find(paper, 'Q2').text).toContain('slope of a velocity-time graph');
    expect(find(paper, 'Q3').text).toContain('maximum height');
    expect(find(paper, 'Q5').text).toContain('Define work');
  });

  it('recovers OCR confusions between Q, O, l and 1', () => {
    const paper = parsePaper(OCR_TEXT);
    expect(parents(paper)).toEqual(['1', '2', '3', '4', '5', '6', '7']);
    expect(find(paper, 'Q1').text).toContain('vector quantity');
    expect(find(paper, 'Q2').text).toContain('velocity-time graph');
    expect(find(paper, 'Q4').text).toContain("Newton's second law");
  });

  it('keeps questions that wrap across lines or pages together', () => {
    const paper = parsePaper(`--- Page 1 ---\n1. Which physical quantity is a\n--- Page 2 ---\nvector quantity? 1\n2. The slope of a velocity-time graph represents which quantity? 1`);
    expect(paper.questions.map(question => question.ref)).toEqual(['Q1', 'Q2']);
    expect(find(paper, 'Q1').text).toContain('vector quantity');
  });

  it('recognises all three sub-parts of Q6 and Q7, in order', () => {
    for (const text of [CLEAN, MERGED, OCR_TEXT]) {
      const paper = parsePaper(text);
      expect(paper.questions.map(question => question.ref)).toEqual(ALL_REFS);
    }
  });

  it('does not turn the MCQ option rows into sub-parts', () => {
    const paper = parsePaper(CLEAN);
    const q1 = find(paper, 'Q1');
    expect(q1.text).toContain('(b) velocity');
    expect(q1.max).toBe(1);
    expect(q1.kind).toBe('objective');
  });

  it('keeps answer options that wrap over two lines out of the sub-parts', () => {
    const paper = parsePaper(`SECTION A
1. Which physical quantity is a vector quantity? 1
(a) speed   (b) velocity
(c) distance   (d) mass
2. The slope of a velocity-time graph represents which quantity? 1
(a) displacement   (b) velocity
(c) acceleration   (d) force`);
    expect(paper.questions.map(question => question.ref)).toEqual(['Q1', 'Q2']);
    expect(paper.questions.map(question => question.max)).toEqual([1, 1]);
    expect(paper.questions[0].text).toContain('(d) mass');
    expect(paper.resolvedTotal).toBe(2);
  });

  it('reads plain trailing marks, including after an option row', () => {
    const paper = parsePaper(CLEAN);
    expect(paper.questions.map(question => question.max)).toEqual([1, 1, 1, 3, 3, 2, 3, 3, 2, 3, 3]);
    expect(paper.questions.every(question => question.marksSource === 'explicit')).toBe(true);
  });

  it('keeps the printed maximum marks at exactly 25', () => {
    for (const text of [CLEAN, MERGED, OCR_TEXT]) {
      const paper = parsePaper(text);
      expect(paper.resolvedTotal).toBe(25);
      expect(paper.printedTotal).toBe(25);
      expect(paper.unresolvedRefs).toEqual([]);
    }
  });

  it('gives Q6 and Q7 eight marks each', () => {
    const paper = parsePaper(CLEAN);
    expect(totalFor(paper, '6')).toBe(8);
    expect(totalFor(paper, '7')).toBe(8);
  });

  it('carries the shared stem so a part is not graded on a fragment', () => {
    const paper = parsePaper(CLEAN);
    expect(find(paper, 'Q7(b)').parentText).toContain('block of mass 5 kg');
    expect(find(paper, 'Q7(b)').parentMax).toBe(8);
    expect(find(paper, 'Q6(c)').parentText).toContain('projectile');
  });

  it('warns about a missing question number instead of silently dropping it', () => {
    const paper = parsePaper(`Maximum Marks: 25\nSECTION A\n1. First question. 1\n3. Third question. 1\n4. Fourth question. 1`);
    expect(paper.warnings.join(' ')).toMatch(/Question number 2 is missing/);
    expect(paper.warnings.join(' ')).toMatch(/states a total of 25 marks, but only 3/);
  });

  it('warns when the recognised marks disagree with the printed total', () => {
    const paper = parsePaper('Maximum Marks: 25\n1. Only question. 1');
    expect(paper.resolvedTotal).toBe(1);
    expect(paper.warnings.join(' ')).toMatch(/states a total of 25 marks, but only 1/);
  });

  it('reads Hindi question labels', () => {
    const paper = parsePaper('प्रश्न 1. नवीकरणीय ऊर्जा का स्रोत बताइए। 2 अंक\nप्रश्न 2. श्वसन को परिभाषित करें। 3 अंक');
    expect(paper.questions.map(question => question.ref)).toEqual(['Q1', 'Q2']);
    expect(paper.questions.map(question => question.max)).toEqual([2, 3]);
  });

  it('does not double-count an internal choice printed as OR', () => {
    const paper = parsePaper(`SECTION B
4. Define reflection of light. 3
OR
4. Define refraction of light. 3`);
    expect(paper.questions).toHaveLength(1);
    expect(paper.questions[0].max).toBe(3);
    expect(paper.resolvedTotal).toBe(3);
    expect(paper.questions[0].choiceText).toContain('refraction');
  });

  it('divides a parent total only when no part marks are printed, and says so', () => {
    const paper = parsePaper('6. Answer both parts. 8\n(a) First part.\n(b) Second part.');
    expect(paper.questions.map(question => question.max)).toEqual([4, 4]);
    expect(paper.resolvedTotal).toBe(8);
    expect(paper.warnings.join(' ')).toMatch(/prints 8 marks in total but no mark for each part/i);
  });
});

describe('Class XI Physics paper: sub-part grading', () => {
  async function markPhysicsPaper(overrides: Record<string, number> = {}) {
    const paper = parsePaper(CLEAN);
    const calls: ChatCall[] = [];
    const report = await evaluatePaper({
      paper,
      answerText: ANSWERS,
      board: 'CBSE',
      grade: 'Class 11',
      chat: decisionChat((ref, max) => {
        if (ref in overrides) {
          return overrides[ref] < 0
            ? { awarded: max + 1, feedback: 'Deliberately out of range for the test.' }
            : { awarded: overrides[ref], feedback: 'Marked against the part requirement.' };
        }
        return { awarded: max, feedback: 'Correct working earns the full part.' };
      }, calls),
    });
    return { report, calls, paper };
  }

  it('marks Q6 and Q7 part by part and can award all 8 marks for correct work', async () => {
    const { report } = await markPhysicsPaper();
    expect(report.grades.map(grade => grade.ref)).toEqual(ALL_REFS);
    expect(report.grades.filter(grade => grade.key.startsWith('7')).map(grade => grade.max)).toEqual([2, 3, 3]);
    expect(report.grades.filter(grade => grade.key.startsWith('7')).map(grade => grade.awarded)).toEqual([2, 3, 3]);
    expect(report.awarded).toBe(25);
    expect(report.paperTotal).toBe(25);
    expect(report.complete).toBe(true);
    expect(report.unresolvedCount).toBe(0);
  });

  it('sends each part with the shared stem and its own allocation', async () => {
    const { calls } = await markPhysicsPaper();
    const prompt = calls.map(call => call.messages.map(message => message.content).join('\n')).join('\n');
    expect(prompt).toContain('Shared question stem: A block of mass 5 kg');
    expect(prompt).toContain('one part of a question worth 8 marks in total');
    expect(refsInPrompt(prompt)).toContainEqual({ ref: 'Q7(b)', max: 3 });
  });

  it('keeps unattempted questions in the denominator with zero', async () => {
    const { report } = await markPhysicsPaper();
    const onlyFirst = await evaluatePaper({
      paper: parsePaper(CLEAN),
      answerText: 'Q1. (b) velocity\nQ2. (c) acceleration\nQ3. 20 m',
      board: 'CBSE',
      grade: 'Class 11',
      chat: decisionChat((_ref, max) => ({ awarded: max, feedback: 'Correct answer.' })),
    });
    expect(onlyFirst.paperTotal).toBe(25);
    expect(onlyFirst.awarded).toBe(3);
    expect(onlyFirst.unattemptedCount).toBe(8);
    expect(onlyFirst.grades.filter(grade => grade.status === 'unattempted').every(grade => grade.awarded === 0)).toBe(true);
    expect(onlyFirst.grades.filter(grade => grade.status === 'unattempted').every(grade => grade.max > 0)).toBe(true);
    expect(report.awarded).toBe(25);
  });

  it('keeps an unverifiable part out of the score instead of calling it zero', async () => {
    const { report } = await markPhysicsPaper({ 'Q7(c)': -1 });
    const q7c = report.grades.find(grade => grade.ref === 'Q7(c)')!;
    expect(q7c.status).toBe('unresolved');
    expect(q7c.awarded).toBe(0);
    expect(report.complete).toBe(false);
    expect(report.paperTotal).toBe(25);
    expect(report.awarded).toBe(22);
    expect(report.unresolvedCount).toBe(1);
  });

  it('splits part answers written on one line into the right parts', async () => {
    const paper = parsePaper(CLEAN);
    const oneLine = `Q1. (b) velocity
Q2. (c) acceleration
Q3. 20 m
Q4. F = ma.
Q5. W = F s, joule.
Q6. (a) T = 2 s. (b) H = 5 m. (c) R = 34.6 m.
Q7. (a) Weight, normal, applied and friction shown. (b) f = 15 N. (c) a = 2 m/s2.`;
    const report = await evaluatePaper({
      paper,
      answerText: oneLine,
      board: 'CBSE',
      grade: 'Class 11',
      chat: decisionChat((_ref, max) => ({ awarded: max, feedback: 'Correct part.' })),
    });
    expect(report.gradedCount).toBe(11);
    expect(report.awarded).toBe(25);
    expect(report.complete).toBe(true);
  });

  it('calculates the percentage from the full paper total, not only attempted questions', async () => {
    const { report } = await markPhysicsPaper({ 'Q1': 0, 'Q2': 0, 'Q3': 0 });
    expect(report.paperTotal).toBe(25);
    expect(report.awarded).toBe(22);
    expect(Math.round((report.awarded / report.paperTotal) * 100)).toBe(88);
  });
});
